/**
 * NicuInvertor — server pentru invertorul MPP Solar PIP-MAX (Cloudflare Worker)
 *
 * Ce face: servește aplicația NicuInvertor și citește datele invertorului din cloud-ul
 * DessMonitor (unde le trimite modulul Wi-Fi prin aplicația Energy-Mate).
 * Parola contului rămâne aici, pe server; în browser ajunge doar PIN-ul tău.
 *
 * Variabile de setat în Cloudflare (Settings → Variables and Secrets):
 *   DESS_USER    contul Energy-Mate / dessmonitor.com (e-mail sau utilizator)
 *   DESS_PASS    parola contului                         (tip Secret)
 *   APP_PIN      PIN-ul cu care deschizi aplicația       (tip Secret)
 * Opționale:
 *   DEVICE_SN    seria invertorului, dacă ai mai multe dispozitive în cont
 *   COMPANY_KEY  cheia platformei (implicit cea de pe dessmonitor.com)
 *   DESS_API     adresa API (implicit https://web.dessmonitor.com/public/)
 */

const APP_HTML = "<!DOCTYPE html>\n<html lang=\"ro\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0a0f1e\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<meta name=\"apple-mobile-web-app-title\" content=\"NicuInvertor\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"icon\" href=\"/icon.svg\" type=\"image/svg+xml\">\n<link rel=\"apple-touch-icon\" href=\"/icon.svg\">\n<title>NicuInvertor</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@400;500;600&family=Manrope:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n/* Layout: one-screen app. Energy-flow hero, then KPI strip, then cards in an auto-fit grid; bottom tab bar on phones, top tabs on wide screens. */\n:root{\n  --bg:#0a0f1e;\n  --surface:rgba(150,170,255,.055);\n  --surface-2:rgba(150,170,255,.09);\n  --line:rgba(160,180,255,.13);\n  --text:#e9edf8;\n  --muted:#8c95b0;\n  --sun:#ffb547;\n  --batt:#38e0c4;\n  --home:#ff7d8f;\n  --grid:#93a0ff;\n  --ok:#52e09a; --warn:#ffcc55; --bad:#ff6b6b;\n  --f-display:\"Unbounded\", \"Segoe UI\", system-ui, sans-serif;\n  --f-body:\"Manrope\", \"Segoe UI\", system-ui, -apple-system, sans-serif;\n  --r:20px;\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nhtml,body{height:100%;margin:0}\nbody{\n  background:var(--bg);color:var(--text);font-family:var(--f-body);font-size:15px;line-height:1.45;\n  -webkit-font-smoothing:antialiased;font-variant-numeric:tabular-nums;\n  background-image:\n    radial-gradient(900px 500px at 50% -180px, rgba(255,181,71,.16), transparent 70%),\n    radial-gradient(700px 500px at -10% 110%, rgba(56,224,196,.09), transparent 70%),\n    radial-gradient(600px 400px at 110% 60%, rgba(147,160,255,.08), transparent 70%);\n  background-attachment:fixed;\n}\nbutton,input,select{font:inherit;color:inherit}\n:focus-visible{outline:2px solid var(--sun);outline-offset:2px;border-radius:8px}\n.app{max-width:1180px;margin:0 auto;padding:calc(14px + env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) calc(96px + env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));display:flex;flex-direction:column;gap:16px}\nheader.top{display:flex;align-items:center;gap:12px;flex-wrap:wrap}\n.brand{display:flex;align-items:center;gap:10px;margin-right:auto}\n.brand-mark{width:36px;height:36px;border-radius:12px;background:conic-gradient(from 200deg,var(--sun),#ff8a3d,var(--sun));display:grid;place-items:center;box-shadow:0 0 24px rgba(255,181,71,.35)}\n.brand h1{font-family:var(--f-display);font-weight:500;font-size:18px;margin:0;letter-spacing:.02em}\n.brand small{display:block;color:var(--muted);font-size:12px;margin-top:1px}\n.pill{display:inline-flex;align-items:center;gap:7px;padding:6px 12px;border-radius:999px;background:var(--surface);border:1px solid var(--line);font-size:12.5px;font-weight:600;white-space:nowrap}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--muted)}\n.pill.ok .dot{background:var(--ok);box-shadow:0 0 10px var(--ok)}\n.pill.warn .dot{background:var(--warn);box-shadow:0 0 10px var(--warn)}\n.pill.bad .dot{background:var(--bad);box-shadow:0 0 10px var(--bad)}\n.pill.demo .dot{background:var(--grid);box-shadow:0 0 10px var(--grid)}\nnav.tabs{display:flex;gap:6px;background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:5px}\nnav.tabs button{border:0;background:transparent;padding:8px 14px;border-radius:12px;cursor:pointer;color:var(--muted);font-weight:600;display:flex;align-items:center;gap:7px}\nnav.tabs button[aria-selected=\"true\"]{background:var(--surface-2);color:var(--text)}\nnav.tabs svg{width:18px;height:18px}\n@media (max-width:760px){\n  nav.tabs{position:fixed;left:12px;right:12px;bottom:calc(10px + env(safe-area-inset-bottom));z-index:20;justify-content:space-around;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);background:rgba(16,22,42,.82);padding:6px}\n  nav.tabs button{flex-direction:column;gap:2px;font-size:11px;padding:7px 10px;flex:1}\n}\n.banner{display:flex;gap:12px;align-items:flex-start;padding:12px 14px;border-radius:14px;background:rgba(147,160,255,.1);border:1px solid rgba(147,160,255,.3);font-size:13.5px}\n.banner[hidden]{display:none}\n.banner b{color:var(--grid)}\n.banner.err{background:rgba(255,107,107,.1);border-color:rgba(255,107,107,.35)}\n.banner.err b{color:var(--bad)}\n.view{display:none;flex-direction:column;gap:16px}\n.view.active{display:flex}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:18px;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);min-width:0}\n.card h2{font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:0 0 14px;display:flex;align-items:center;gap:8px}\n.card h2 .tag{margin-left:auto;text-transform:none;letter-spacing:0;font-weight:600}\n.hero{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:16px}\n@media (max-width:900px){.hero{grid-template-columns:1fr}}\n.flow-card{padding:10px 10px 6px;position:relative;overflow:hidden}\n.flow-card svg{width:100%;height:auto;display:block}\n.flow-meta{position:absolute;left:18px;top:14px;font-size:12px;color:var(--muted)}\n.flow-meta strong{display:block;color:var(--text);font-family:var(--f-display);font-weight:500;font-size:13px}\n.node-val{font-family:var(--f-display);font-weight:500;font-size:17px;fill:var(--text)}\n.node-lbl{font-size:11px;fill:var(--muted);font-weight:600;letter-spacing:.06em;text-transform:uppercase}\n.wire{fill:none;stroke:rgba(160,180,255,.14);stroke-width:3}\n.flowline{fill:none;stroke-width:4;stroke-linecap:round;stroke-dasharray:1 15;animation:flow var(--dur,2s) linear infinite;filter:drop-shadow(0 0 4px currentColor)}\n.flowline.rev{animation-direction:reverse}\n.flowline.off{opacity:0}\n@keyframes flow{to{stroke-dashoffset:-32}}\n@media (prefers-reduced-motion:reduce){.flowline{animation:none;stroke-dasharray:none;stroke-width:2.5;opacity:.7}}\n.side{display:grid;gap:16px;grid-template-rows:auto 1fr}\n.kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.kpi{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:14px 14px 12px;position:relative;overflow:hidden}\n.kpi::before{content:\"\";position:absolute;left:0;top:14px;bottom:14px;width:3px;border-radius:3px;background:var(--c,var(--sun))}\n.kpi .lbl{font-size:12px;color:var(--muted);font-weight:600}\n.kpi .val{font-family:var(--f-display);font-size:24px;font-weight:500;margin-top:4px;white-space:nowrap}\n.kpi .val small{font-family:var(--f-body);font-size:13px;color:var(--muted);font-weight:600;margin-left:3px}\n.kpi .sub{font-size:12px;color:var(--muted);margin-top:2px}\n.batt{display:flex;gap:18px;align-items:center}\n.ring{position:relative;width:128px;height:128px;flex:none}\n.ring svg{width:100%;height:100%;transform:rotate(-90deg)}\n.ring .center{position:absolute;inset:0;display:grid;place-items:center;text-align:center}\n.ring .pct{font-family:var(--f-display);font-size:28px;font-weight:500;line-height:1}\n.ring .pct small{font-size:14px}\n.ring .st{font-size:11.5px;color:var(--muted);margin-top:4px;font-weight:600}\n.stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 16px;flex:1;min-width:0}\n.stat .k{font-size:12px;color:var(--muted);font-weight:600}\n.stat .v{font-weight:700;font-size:16px}\n.grid-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}\n.chart-wrap{position:relative}\n.chart-wrap svg{display:block;width:100%}\n.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:12.5px;color:var(--muted);font-weight:600;margin-top:8px}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px;vertical-align:-1px}\n.tip{position:absolute;pointer-events:none;background:rgba(14,20,40,.94);border:1px solid var(--line);border-radius:12px;padding:9px 11px;font-size:12.5px;min-width:150px;box-shadow:0 10px 30px rgba(0,0,0,.4);opacity:0;transition:opacity .12s}\n.tip .t{font-weight:700;margin-bottom:4px}\n.tip div{display:flex;justify-content:space-between;gap:12px}\n.seg{display:inline-flex;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:3px}\n.seg button{border:0;background:transparent;padding:5px 10px;border-radius:9px;color:var(--muted);font-weight:600;cursor:pointer;font-size:12.5px}\n.seg button[aria-pressed=\"true\"]{background:var(--surface-2);color:var(--text)}\n.bar{height:8px;border-radius:8px;background:rgba(160,180,255,.1);overflow:hidden;margin:6px 0 2px}\n.bar > span{display:block;height:100%;border-radius:8px;background:linear-gradient(90deg,#ff8a3d,var(--sun));transition:width .6s ease}\n.rows{display:grid;gap:10px}\n.row{display:flex;justify-content:space-between;gap:12px;align-items:baseline}\n.row .k{color:var(--muted);font-size:13.5px}\n.row .v{font-weight:700}\n.chip{display:inline-flex;align-items:center;gap:6px;padding:3px 9px;border-radius:999px;font-size:12px;font-weight:700;background:var(--surface-2)}\n.chip.ok{color:var(--ok)} .chip.warn{color:var(--warn)} .chip.bad{color:var(--bad)}\n.search{width:100%;padding:11px 14px;border-radius:12px;border:1px solid var(--line);background:var(--surface);outline:none}\n.search:focus{border-color:rgba(255,181,71,.5)}\ntable.params{width:100%;border-collapse:collapse;font-size:13.5px}\ntable.params td{padding:8px 4px;border-bottom:1px solid var(--line)}\ntable.params td:last-child{text-align:right;font-weight:700;white-space:nowrap}\ntable.params tr:last-child td{border-bottom:0}\n.steps{counter-reset:s;display:grid;gap:12px;margin:0;padding:0;list-style:none}\n.steps li{counter-increment:s;display:grid;grid-template-columns:34px 1fr;gap:12px;align-items:start}\n.steps li::before{content:counter(s);width:30px;height:30px;border-radius:10px;display:grid;place-items:center;background:var(--surface-2);font-family:var(--f-display);font-size:13px;color:var(--sun)}\n.steps b{display:block}\n.steps p{margin:2px 0 0;color:var(--muted);font-size:13.5px;max-width:65ch}\nlabel.field{display:grid;gap:6px;font-size:13px;color:var(--muted);font-weight:600}\n.input{padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:var(--surface);outline:none;width:100%}\n.btn{border:1px solid var(--line);background:var(--surface-2);padding:10px 16px;border-radius:12px;font-weight:700;cursor:pointer}\n.btn.primary{background:linear-gradient(135deg,var(--sun),#ff8a3d);color:#1a1205;border:0}\n.btn:hover{filter:brightness(1.08)}\n.toggle{display:flex;align-items:center;justify-content:space-between;gap:12px}\n.switch{position:relative;width:44px;height:26px;flex:none}\n.switch input{opacity:0;width:0;height:0}\n.switch span{position:absolute;inset:0;border-radius:99px;background:rgba(160,180,255,.18);transition:.2s;cursor:pointer}\n.switch span::after{content:\"\";position:absolute;left:3px;top:3px;width:20px;height:20px;border-radius:50%;background:#fff;transition:.2s}\n.switch input:checked + span{background:var(--sun)}\n.switch input:checked + span::after{transform:translateX(18px)}\n.lock{position:fixed;inset:0;z-index:50;display:none;place-items:center;background:rgba(6,9,20,.86);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);padding:20px}\n.lock.show{display:grid}\n.lock .card{max-width:360px;width:100%;text-align:center;display:grid;gap:14px}\n.lock input{text-align:center;font-size:22px;letter-spacing:.4em;font-family:var(--f-display)}\n.muted{color:var(--muted)}\n.small{font-size:12.5px}\n.err-text{color:var(--bad);font-size:13px;min-height:18px}\n.updated{font-size:12px;color:var(--muted)}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <header class=\"top\">\n    <div class=\"brand\">\n      <div class=\"brand-mark\" aria-hidden=\"true\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#1a1205\" stroke-width=\"2.2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"4.2\"/><path d=\"M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M5.3 18.7l1.6-1.6M17.1 6.9l1.6-1.6\"/></svg>\n      </div>\n      <div><h1>NicuInvertor</h1><small id=\"devName\">MPP Solar PIP-MAX 11 kW</small></div>\n    </div>\n    <span class=\"pill\" id=\"statusPill\"><span class=\"dot\"></span><span id=\"statusText\">Se conectează…</span></span>\n    <nav class=\"tabs\" role=\"tablist\" aria-label=\"Secțiuni\">\n      <button role=\"tab\" id=\"tab-acasa\" aria-selected=\"true\" data-view=\"acasa\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 2 4 14h7l-1 8 9-12h-7z\"/></svg>Acum</button>\n      <button role=\"tab\" id=\"tab-istoric\" aria-selected=\"false\" data-view=\"istoric\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 3v18h18\"/><path d=\"m7 15 4-5 3 3 5-7\"/></svg>Istoric</button>\n      <button role=\"tab\" id=\"tab-detalii\" aria-selected=\"false\" data-view=\"detalii\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M4 6h16M4 12h16M4 18h10\"/></svg>Detalii</button>\n      <button role=\"tab\" id=\"tab-setari\" aria-selected=\"false\" data-view=\"setari\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z\"/></svg>Setări</button>\n    </nav>\n  </header>\n\n  <div class=\"banner\" id=\"banner\" hidden></div>\n\n  <!-- ACUM -->\n  <section class=\"view active\" id=\"view-acasa\" role=\"tabpanel\" aria-labelledby=\"tab-acasa\">\n    <div class=\"hero\">\n      <div class=\"card flow-card\" id=\"flow\">\n        <div class=\"flow-meta\"><strong id=\"modeText\">—</strong><span id=\"updatedText\" class=\"updated\">—</span></div>\n        <svg viewBox=\"0 0 400 330\" role=\"img\" aria-label=\"Fluxul de energie în timp real\">\n          <defs>\n            <radialGradient id=\"gInv\" cx=\"50%\" cy=\"35%\" r=\"70%\"><stop offset=\"0\" stop-color=\"#2a3560\"/><stop offset=\"1\" stop-color=\"#151c36\"/></radialGradient>\n            <filter id=\"glow\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feGaussianBlur stdDeviation=\"6\"/></filter>\n          </defs>\n          <!-- wires -->\n          <path id=\"w-pv\"   class=\"wire\" d=\"M200 92 V136\"/>\n          <path id=\"w-bat\"  class=\"wire\" d=\"M92 182 H152\"/>\n          <path id=\"w-load\" class=\"wire\" d=\"M248 182 H308\"/>\n          <path id=\"w-grid\" class=\"wire\" d=\"M200 228 V262\"/>\n          <path id=\"f-pv\"   class=\"flowline\" style=\"color:var(--sun);stroke:var(--sun)\"   d=\"M200 92 V136\"/>\n          <path id=\"f-bat\"  class=\"flowline\" style=\"color:var(--batt);stroke:var(--batt)\" d=\"M152 182 H92\"/>\n          <path id=\"f-load\" class=\"flowline\" style=\"color:var(--home);stroke:var(--home)\" d=\"M248 182 H308\"/>\n          <path id=\"f-grid\" class=\"flowline\" style=\"color:var(--grid);stroke:var(--grid)\" d=\"M200 262 V228\"/>\n          <!-- inverter -->\n          <rect x=\"152\" y=\"136\" width=\"96\" height=\"92\" rx=\"22\" fill=\"url(#gInv)\" stroke=\"rgba(160,180,255,.25)\"/>\n          <g transform=\"translate(200 170)\" stroke=\"#cfd6ff\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\">\n            <rect x=\"-15\" y=\"-14\" width=\"30\" height=\"28\" rx=\"6\"/>\n            <path d=\"M-8 4 q4 -9 8 0 t8 0\" stroke=\"var(--sun)\"/>\n          </g>\n          <text x=\"200\" y=\"212\" text-anchor=\"middle\" class=\"node-lbl\" style=\"fill:#cfd6ff\">Invertor</text>\n          <!-- solar -->\n          <g id=\"n-pv\" transform=\"translate(200 52)\">\n            <circle r=\"40\" fill=\"var(--sun)\" opacity=\".18\" filter=\"url(#glow)\" id=\"pvGlow\"/>\n            <circle r=\"34\" fill=\"#1a1d2e\" stroke=\"var(--sun)\" stroke-width=\"2\"/>\n            <g stroke=\"var(--sun)\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"><circle r=\"8\"/><path d=\"M0-17v4M0 13v4M-17 0h4M13 0h4M-12-12l3 3M9 9l3 3M-12 12l3-3M9-9l3-3\"/></g>\n          </g>\n          <text x=\"258\" y=\"46\" class=\"node-lbl\">Panouri</text>\n          <text x=\"258\" y=\"68\" class=\"node-val\" id=\"v-pv\">—</text>\n          <!-- battery -->\n          <g transform=\"translate(56 182)\">\n            <circle r=\"34\" fill=\"#16202a\" stroke=\"var(--batt)\" stroke-width=\"2\"/>\n            <rect x=\"-10\" y=\"-15\" width=\"20\" height=\"30\" rx=\"4\" fill=\"none\" stroke=\"var(--batt)\" stroke-width=\"2\"/>\n            <rect x=\"-4\" y=\"-19\" width=\"8\" height=\"4\" rx=\"1.5\" fill=\"var(--batt)\"/>\n            <rect id=\"battFill\" x=\"-6.5\" y=\"-11.5\" width=\"13\" height=\"23\" rx=\"2\" fill=\"var(--batt)\" opacity=\".85\"/>\n          </g>\n          <text x=\"56\" y=\"240\" text-anchor=\"middle\" class=\"node-lbl\">Baterie</text>\n          <text x=\"56\" y=\"262\" text-anchor=\"middle\" class=\"node-val\" id=\"v-bat\">—</text>\n          <text x=\"56\" y=\"280\" text-anchor=\"middle\" class=\"node-lbl\" id=\"v-batdir\" style=\"text-transform:none;letter-spacing:0\">—</text>\n          <!-- home -->\n          <g transform=\"translate(344 182)\">\n            <circle r=\"34\" fill=\"#25161c\" stroke=\"var(--home)\" stroke-width=\"2\"/>\n            <path d=\"M-14 1 0-12 14 1M-10-2v14h20V-2M-3 12V4h6v8\" fill=\"none\" stroke=\"var(--home)\" stroke-width=\"2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/>\n          </g>\n          <text x=\"344\" y=\"240\" text-anchor=\"middle\" class=\"node-lbl\">Casă</text>\n          <text x=\"344\" y=\"262\" text-anchor=\"middle\" class=\"node-val\" id=\"v-load\">—</text>\n          <text x=\"344\" y=\"280\" text-anchor=\"middle\" class=\"node-lbl\" id=\"v-loadpct\" style=\"text-transform:none;letter-spacing:0\">—</text>\n          <!-- grid -->\n          <g transform=\"translate(200 296)\">\n            <circle r=\"30\" fill=\"#181b33\" stroke=\"var(--grid)\" stroke-width=\"2\"/>\n            <path d=\"M-8 14 0-14 8 14M-11-6h22M-9 2h18M-5-6l10 8M5-6-5 2\" fill=\"none\" stroke=\"var(--grid)\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n          </g>\n          <text x=\"244\" y=\"292\" class=\"node-lbl\">Rețea</text>\n          <text x=\"244\" y=\"313\" class=\"node-val\" id=\"v-grid\">—</text>\n        </svg>\n      </div>\n\n      <div class=\"side\">\n        <div class=\"kpis\">\n          <div class=\"kpi\" style=\"--c:var(--sun)\"><div class=\"lbl\">Produs azi</div><div class=\"val\" id=\"k-prod\">—</div><div class=\"sub\" id=\"k-prod-sub\">din panouri</div></div>\n          <div class=\"kpi\" style=\"--c:var(--home)\"><div class=\"lbl\">Consumat azi</div><div class=\"val\" id=\"k-cons\">—</div><div class=\"sub\" id=\"k-cons-sub\">de casă</div></div>\n          <div class=\"kpi\" style=\"--c:var(--batt)\"><div class=\"lbl\">Autonomie</div><div class=\"val\" id=\"k-auto\">—</div><div class=\"sub\" id=\"k-auto-sub\">la consumul actual</div></div>\n          <div class=\"kpi\" style=\"--c:var(--grid)\"><div class=\"lbl\">Din soare</div><div class=\"val\" id=\"k-self\">—</div><div class=\"sub\">din consumul de azi</div></div>\n        </div>\n        <div class=\"card\">\n          <h2>Baterie <span class=\"tag chip\" id=\"battChip\">—</span></h2>\n          <div class=\"batt\">\n            <div class=\"ring\">\n              <svg viewBox=\"0 0 120 120\"><circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"rgba(160,180,255,.1)\" stroke-width=\"11\"/><circle id=\"ringArc\" cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"var(--batt)\" stroke-width=\"11\" stroke-linecap=\"round\" stroke-dasharray=\"314.16\" stroke-dashoffset=\"314.16\" style=\"transition:stroke-dashoffset .9s ease, stroke .3s\"/></svg>\n              <div class=\"center\"><div><div class=\"pct\" id=\"socText\">—<small>%</small></div><div class=\"st\" id=\"battState\">—</div></div></div>\n            </div>\n            <div class=\"stats\">\n              <div class=\"stat\"><div class=\"k\">Tensiune</div><div class=\"v\" id=\"b-v\">—</div></div>\n              <div class=\"stat\"><div class=\"k\">Curent</div><div class=\"v\" id=\"b-a\">—</div></div>\n              <div class=\"stat\"><div class=\"k\">Putere</div><div class=\"v\" id=\"b-w\">—</div></div>\n              <div class=\"stat\"><div class=\"k\" id=\"b-eta-k\">Estimare</div><div class=\"v\" id=\"b-eta\">—</div></div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\" id=\"todayCard\">\n      <h2>Azi <span class=\"tag updated\" id=\"todayNote\"></span></h2>\n      <div class=\"chart-wrap\" id=\"chartToday\"></div>\n      <div class=\"legend\"><span><i style=\"background:var(--sun)\"></i>Producție</span><span><i style=\"background:var(--home)\"></i>Consum</span><span><i style=\"background:var(--batt)\"></i>Baterie (+ încarcă / − descarcă)</span></div>\n    </div>\n\n    <div class=\"grid-cards\">\n      <div class=\"card\" id=\"pvCard\">\n        <h2>Panouri pe intrări</h2>\n        <div class=\"rows\" id=\"pvRows\"></div>\n      </div>\n      <div class=\"card\" id=\"outCard\">\n        <h2>Ieșire invertor</h2>\n        <div class=\"rows\">\n          <div class=\"row\"><span class=\"k\">Tensiune ieșire</span><span class=\"v\" id=\"o-v\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Frecvență</span><span class=\"v\" id=\"o-hz\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Încărcare invertor</span><span class=\"v\" id=\"o-pct\">—</span></div>\n          <div class=\"bar\"><span id=\"o-bar\" style=\"width:0%\"></span></div>\n          <div class=\"row\"><span class=\"k\">Temperatură</span><span class=\"v\" id=\"o-temp\">—</span></div>\n        </div>\n      </div>\n      <div class=\"card\" id=\"gridCard\">\n        <h2>Rețea electrică <span class=\"tag chip\" id=\"gridChip\">—</span></h2>\n        <div class=\"rows\">\n          <div class=\"row\"><span class=\"k\">Tensiune rețea</span><span class=\"v\" id=\"g-v\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Frecvență rețea</span><span class=\"v\" id=\"g-hz\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Putere din rețea</span><span class=\"v\" id=\"g-w\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Luat din rețea azi</span><span class=\"v\" id=\"g-today\">—</span></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ISTORIC -->\n  <section class=\"view\" id=\"view-istoric\" role=\"tabpanel\" aria-labelledby=\"tab-istoric\">\n    <div class=\"card\">\n      <h2>Ziua aleasă\n        <span class=\"tag\" style=\"display:flex;gap:8px;align-items:center\">\n          <button class=\"btn\" id=\"dayPrev\" aria-label=\"Ziua anterioară\" style=\"padding:6px 11px\">‹</button>\n          <input type=\"date\" id=\"dayPick\" class=\"input\" style=\"width:auto;padding:6px 10px\">\n          <button class=\"btn\" id=\"dayNext\" aria-label=\"Ziua următoare\" style=\"padding:6px 11px\">›</button>\n        </span>\n      </h2>\n      <div class=\"chart-wrap\" id=\"chartDay\"></div>\n      <div class=\"legend\"><span><i style=\"background:var(--sun)\"></i>Producție</span><span><i style=\"background:var(--home)\"></i>Consum</span><span><i style=\"background:var(--batt)\"></i>Baterie</span></div>\n    </div>\n    <div class=\"kpis\" style=\"grid-template-columns:repeat(auto-fit,minmax(160px,1fr))\">\n      <div class=\"kpi\" style=\"--c:var(--sun)\"><div class=\"lbl\">Produs</div><div class=\"val\" id=\"d-prod\">—</div></div>\n      <div class=\"kpi\" style=\"--c:var(--home)\"><div class=\"lbl\">Consumat</div><div class=\"val\" id=\"d-cons\">—</div></div>\n      <div class=\"kpi\" style=\"--c:var(--sun)\"><div class=\"lbl\">Vârf producție</div><div class=\"val\" id=\"d-peak\">—</div><div class=\"sub\" id=\"d-peak-t\"></div></div>\n      <div class=\"kpi\" style=\"--c:var(--grid)\"><div class=\"lbl\">Economie estimată</div><div class=\"val\" id=\"d-save\">—</div><div class=\"sub\" id=\"d-save-sub\">la prețul din Setări</div></div>\n    </div>\n  </section>\n\n  <!-- DETALII -->\n  <section class=\"view\" id=\"view-detalii\" role=\"tabpanel\" aria-labelledby=\"tab-detalii\">\n    <input class=\"search\" id=\"paramSearch\" type=\"search\" placeholder=\"Caută un parametru (ex: tensiune, PV2, temperatură)\" aria-label=\"Caută parametru\">\n    <div class=\"grid-cards\" id=\"paramGroups\"></div>\n  </section>\n\n  <!-- SETARI -->\n  <section class=\"view\" id=\"view-setari\" role=\"tabpanel\" aria-labelledby=\"tab-setari\">\n    <div class=\"grid-cards\">\n      <div class=\"card\">\n        <h2>Sistemul tău</h2>\n        <div class=\"rows\" style=\"gap:14px\">\n          <label class=\"field\" for=\"setCap\">Capacitate baterie (kWh)\n            <input class=\"input\" id=\"setCap\" type=\"number\" min=\"1\" max=\"200\" step=\"0.1\">\n          </label>\n          <label class=\"field\" for=\"setPrice\">Preț energie (lei / kWh)\n            <input class=\"input\" id=\"setPrice\" type=\"number\" min=\"0\" max=\"10\" step=\"0.01\">\n          </label>\n          <label class=\"field\" for=\"setReserve\">Rezervă minimă baterie (%)\n            <input class=\"input\" id=\"setReserve\" type=\"number\" min=\"0\" max=\"80\" step=\"1\">\n          </label>\n          <div class=\"toggle\"><span><b>Date demonstrative</b><br><span class=\"muted small\">Arată aplicația cu valori simulate</span></span>\n            <label class=\"switch\"><input type=\"checkbox\" id=\"setDemo\"><span></span></label></div>\n          <button class=\"btn\" id=\"logoutBtn\">Blochează aplicația (cere PIN din nou)</button>\n        </div>\n      </div>\n      <div class=\"card\">\n        <h2>Conexiune</h2>\n        <div class=\"rows\">\n          <div class=\"row\"><span class=\"k\">Sursă date</span><span class=\"v\" id=\"c-src\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Colector Wi-Fi (PN)</span><span class=\"v\" id=\"c-pn\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Serie invertor</span><span class=\"v\" id=\"c-sn\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Ultima raportare</span><span class=\"v\" id=\"c-last\">—</span></div>\n          <div class=\"row\"><span class=\"k\">Reîmprospătare</span><span class=\"v\">la 30 de secunde</span></div>\n        </div>\n        <p class=\"muted small\" style=\"margin:14px 0 0\">Invertorul trimite date în cloud cam o dată la 5 minute, deci valorile se schimbă în pașii aceștia.</p>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h2>Cum conectezi invertorul</h2>\n      <ol class=\"steps\">\n        <li><div><b>Instalează Energy-Mate pe telefon</b><p>Din App Store sau Google Play. Îți faci cont cu e-mail și parolă. Este aplicația oficială MPP Solar, care înlocuiește WatchPower.</p></div></li>\n        <li><div><b>Adaugă invertorul în aplicație</b><p>Scanezi codul QR sau introduci PN-ul (numărul de 14 caractere) de pe eticheta modulului Wi-Fi al invertorului.</p></div></li>\n        <li><div><b>Conectează-l la Wi-Fi-ul casei</b><p>Aplicația te trece pe rețeaua Wi-Fi emisă de invertor, apoi alegi rețeaua casei și scrii parola. Folosește rețeaua de 2,4 GHz; modulul nu vede 5 GHz.</p></div></li>\n        <li><div><b>Verifică pe dessmonitor.com</b><p>Intră cu același cont pe dessmonitor.com. Dacă vezi invertorul acolo, NicuInvertor poate citi datele.</p></div></li>\n        <li><div><b>Pornește serverul NicuInvertor</b><p>Urmezi ghidul primit împreună cu aplicația: lipești fișierul worker.js în contul tău gratuit Cloudflare și pui contul Energy-Mate și un PIN. Primești o adresă pe care o deschizi de oriunde.</p></div></li>\n      </ol>\n    </div>\n  </section>\n</div>\n\n<div class=\"lock\" id=\"lock\">\n  <form class=\"card\" id=\"pinForm\">\n    <div class=\"brand-mark\" style=\"margin:0 auto;width:48px;height:48px\" aria-hidden=\"true\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#1a1205\" stroke-width=\"2.2\" stroke-linecap=\"round\"><rect x=\"5\" y=\"11\" width=\"14\" height=\"10\" rx=\"2\"/><path d=\"M8 11V8a4 4 0 0 1 8 0v3\"/></svg></div>\n    <div><b style=\"font-family:var(--f-display);font-weight:500;font-size:18px\">NicuInvertor e blocat</b><p class=\"muted small\" style=\"margin:6px 0 0\">Scrie PIN-ul pe care l-ai setat în Cloudflare.</p></div>\n    <input class=\"input\" id=\"pinInput\" type=\"password\" inputmode=\"numeric\" autocomplete=\"current-password\" aria-label=\"PIN\" maxlength=\"32\">\n    <div class=\"err-text\" id=\"pinErr\"></div>\n    <button class=\"btn primary\" type=\"submit\">Deblochează</button>\n  </form>\n</div>\n\n<script>\n(() => {\n\"use strict\";\n/* ---------- utils ---------- */\nconst $ = id => document.getElementById(id);\nconst store = {\n  get(k, d){ try{ const v = localStorage.getItem(\"nicuinvertor:\"+k); return v === null ? d : JSON.parse(v); }catch(e){ return d; } },\n  set(k, v){ try{ localStorage.setItem(\"nicuinvertor:\"+k, JSON.stringify(v)); }catch(e){} }\n};\nconst settings = {\n  cap: store.get(\"cap\", 10), price: store.get(\"price\", 1.3), reserve: store.get(\"reserve\", 20), demo: store.get(\"demo\", false)\n};\nconst nf1 = new Intl.NumberFormat(\"ro-RO\",{maximumFractionDigits:1, minimumFractionDigits:1});\nconst nf0 = new Intl.NumberFormat(\"ro-RO\",{maximumFractionDigits:0});\nconst nf2 = new Intl.NumberFormat(\"ro-RO\",{maximumFractionDigits:2, minimumFractionDigits:2});\nconst isNum = v => typeof v === \"number\" && isFinite(v);\nconst fmtW = w => !isNum(w) ? \"—\" : Math.abs(w) >= 1000 ? nf1.format(w/1000)+\" kW\" : nf0.format(w)+\" W\";\nconst fmtKwh = k => !isNum(k) ? \"—\" : (k >= 100 ? nf0.format(k) : nf1.format(k));\nconst fmtU = (v, u, f=nf1) => !isNum(v) ? \"—\" : f.format(v)+\" \"+u;\nconst fmtDur = h => { if(!isNum(h) || h < 0) return \"—\"; if(h > 99) return \"> 99 h\"; const H = Math.floor(h), M = Math.round((h-H)*60); return H ? `${H} h ${String(M).padStart(2,\"0\")}` : `${M} min`; };\nconst clamp = (x,a,b) => Math.max(a, Math.min(b, x));\nconst pad2 = n => String(n).padStart(2,\"0\");\nconst ymd = d => `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`;\nconst hm = d => `${pad2(d.getHours())}:${pad2(d.getMinutes())}`;\nconst setText = (id, t) => { const el = $(id); if(el) el.textContent = t; };\n\n/* ---------- API ---------- */\nlet mode = \"detect\"; // \"live\" | \"demo\"\nlet pin = store.get(\"pin\", \"\");\nasync function api(path){\n  const r = await fetch(path + (path.includes(\"?\") ? \"&\" : \"?\") + \"tz=\" + new Date().getTimezoneOffset(), {headers: pin ? {\"x-pin\": pin} : {}, cache:\"no-store\"});\n  if(r.status === 401){ showLock(true); throw new Error(\"PIN\"); }\n  const j = await r.json().catch(() => ({}));\n  if(!r.ok || j.error) throw new Error(j.error || (\"HTTP \"+r.status));\n  return j;\n}\nasync function detect(){\n  if(settings.demo){ mode = \"demo\"; return; }\n  try{\n    const r = await fetch(\"/api/ping\", {cache:\"no-store\"});\n    const j = await r.json();\n    if(!j || j.app !== \"nicuinvertor\") throw 0;\n    mode = \"live\";\n    if(!j.configured){ banner(\"err\", \"<b>Serverul nu e configurat.</b> Adaugă în Cloudflare variabilele DESS_USER, DESS_PASS și APP_PIN, apoi reîncarcă pagina.\"); }\n    if(!pin) showLock(true);\n  }catch(e){ mode = \"demo\"; }\n}\nfunction banner(kind, html){\n  const b = $(\"banner\");\n  if(!html){ b.hidden = true; return; }\n  b.className = \"banner\" + (kind === \"err\" ? \" err\" : \"\");\n  b.innerHTML = html; b.hidden = false;\n}\n\n/* ---------- demo data (Bucharest, November, 8 kWp array, 10 kWh battery) ---------- */\nconst demo = (() => {\n  let seed = 7;\n  const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;\n  function cloud(t){ return .72 + .2*Math.sin(t/2.3) + .08*Math.sin(t*3.1+1); }\n  function pvAt(h){ const rise = 7.15, set = 16.75; if(h <= rise || h >= set) return 0; const x = (h-rise)/(set-rise); return 4700*Math.pow(Math.sin(Math.PI*x),1.5)*cloud(h); }\n  function loadAt(h, k){ let w = 330 + 90*Math.sin(h*1.7); if(h > 6.5 && h < 8.5) w += 900; if(h > 12 && h < 13.5) w += 1200; if(h > 17.5 && h < 22.5) w += 1100 + 400*Math.sin(h*2); if(k % 41 === 7 && h > 7 && h < 22) w += 1800; return w; }\n  function day(date){\n    seed = date.getDate()*131 + date.getMonth()*17 + 7;\n    const now = new Date(); const isToday = ymd(date) === ymd(now);\n    const endH = isToday ? now.getHours() + now.getMinutes()/60 : 24;\n    const capWh = settings.cap*1000; let soc = 58 + 10*rnd();\n    const s = {pv:[], load:[], battery:[], grid:[], soc:[]};\n    const base = new Date(date); base.setHours(0,0,0,0);\n    for(let k = 0, h = 0; h <= endH; k++, h = k*5/60){\n      const t = base.getTime() + k*300000;\n      const pv = Math.max(0, pvAt(h) * (0.9 + 0.2*rnd()));\n      const load = loadAt(h, k) * (0.9 + 0.2*rnd());\n      let bat = pv - load; let grid = 0;\n      if(bat > 0 && soc >= 100) bat = 0;\n      if(bat < 0 && soc <= settings.reserve){ grid = -bat; bat = 0; }\n      soc = clamp(soc + bat*(5/60)/capWh*100, 0, 100);\n      s.pv.push([t, pv]); s.load.push([t, load]); s.battery.push([t, bat]); s.grid.push([t, grid]); s.soc.push([t, soc]);\n    }\n    return s;\n  }\n  function live(){\n    const d = day(new Date()); const L = a => a[a.length-1][1];\n    const pv = L(d.pv), load = L(d.load), bat = L(d.battery), grid = L(d.grid), soc = L(d.soc);\n    const bv = 50.2 + soc*0.05 + (bat > 0 ? 1.2 : -0.4); const ba = bat / bv;\n    const pv1 = pv*0.52, pv2 = pv - pv1;\n    const pv1v = pv1 > 5 ? 352 + rnd()*20 : 18, pv2v = pv2 > 5 ? 348 + rnd()*20 : 15;\n    const out = {\n      ts: Date.now() - 90000, online: true, mode: \"Battery Mode\", source: \"demo\",\n      device: {pn:\"W0012345678901\", sn:\"96342207100417\", alias:\"PIP-MAX 11KW\"},\n      pv: {power: pv, strings:[{v:pv1v, a:pv1/pv1v, w:pv1},{v:pv2v, a:pv2/pv2v, w:pv2}]},\n      battery: {soc, voltage: bv, current: ba, power: bat},\n      load: {power: load, percent: load/11000*100},\n      output: {voltage: 230.1, freq: 50.0},\n      grid: {voltage: grid > 0 ? 231.4 : 0, freq: grid > 0 ? 50.0 : 0, power: grid, present: grid > 0},\n      temp: 38 + pv/400,\n    };\n    out.params = [\n      {group:\"Rețea\", par:\"Grid Voltage\", val: nf1.format(out.grid.voltage), unit:\"V\"},\n      {group:\"Rețea\", par:\"Grid Frequency\", val: nf2.format(out.grid.freq), unit:\"Hz\"},\n      {group:\"Fotovoltaic\", par:\"PV1 Input Voltage\", val: nf1.format(pv1v), unit:\"V\"},\n      {group:\"Fotovoltaic\", par:\"PV1 Charging Power\", val: nf0.format(pv1), unit:\"W\"},\n      {group:\"Fotovoltaic\", par:\"PV2 Input Voltage\", val: nf1.format(pv2v), unit:\"V\"},\n      {group:\"Fotovoltaic\", par:\"PV2 Charging Power\", val: nf0.format(pv2), unit:\"W\"},\n      {group:\"Baterie\", par:\"Battery Voltage\", val: nf2.format(bv), unit:\"V\"},\n      {group:\"Baterie\", par:\"Battery Capacity\", val: nf0.format(soc), unit:\"%\"},\n      {group:\"Baterie\", par:bat >= 0 ? \"Battery Charging Current\" : \"Battery Discharge Current\", val: nf1.format(Math.abs(ba)), unit:\"A\"},\n      {group:\"Consum\", par:\"AC Output Voltage\", val: \"230,1\", unit:\"V\"},\n      {group:\"Consum\", par:\"AC Output Frequency\", val: \"50,00\", unit:\"Hz\"},\n      {group:\"Consum\", par:\"AC Output Active Power\", val: nf0.format(load), unit:\"W\"},\n      {group:\"Consum\", par:\"Output Load Percent\", val: nf0.format(out.load.percent), unit:\"%\"},\n      {group:\"Sistem\", par:\"Working State\", val: \"Battery Mode\", unit:\"\"},\n      {group:\"Sistem\", par:\"Inverter Heat Sink Temperature\", val: nf0.format(out.temp), unit:\"°C\"},\n      {group:\"Sistem\", par:\"Main CPU Firmware Version\", val: \"00062.08\", unit:\"\"},\n    ];\n    return out;\n  }\n  return {live, day};\n})();\n\n/* ---------- data load ---------- */\nconst getLive = () => mode === \"demo\" ? Promise.resolve(demo.live()) : api(\"/api/live\");\nconst getDay = date => mode === \"demo\" ? Promise.resolve(demo.day(date)) : api(\"/api/day?date=\"+ymd(date));\n\n/* ---------- energy math ---------- */\nfunction integrate(series, sign = 0){ // Wh -> kWh, trapezoid; sign: 1 only positive, -1 only negative\n  let wh = 0;\n  for(let i = 1; i < (series||[]).length; i++){\n    const [t0, a] = series[i-1], [t1, b] = series[i]; const dt = (t1 - t0)/3600000;\n    if(dt <= 0 || dt > 1) continue;\n    let x = a, y = b; if(sign === 1){ x = Math.max(0,x); y = Math.max(0,y); } else if(sign === -1){ x = Math.min(0,x); y = Math.min(0,y); }\n    wh += (x + y)/2*dt;\n  }\n  return wh/1000;\n}\n\n/* ---------- render: live ---------- */\nconst MODES = {\"battery mode\":\"Pe baterie\",\"line mode\":\"Pe rețea\",\"standby mode\":\"În așteptare\",\"standby\":\"În așteptare\",\"fault mode\":\"Defecțiune\",\"power saving mode\":\"Economic\",\"power on mode\":\"Pornire\",\"bypass mode\":\"Bypass\",\"hybrid mode\":\"Hibrid\"};\nconst modeRo = m => { if(!m) return \"—\"; const k = String(m).toLowerCase().trim(); return MODES[k] || m; };\nfunction setFlow(id, watts, reverse){\n  const el = $(id); const w = Math.abs(watts||0);\n  if(!isNum(watts) || w < 15){ el.classList.add(\"off\"); return; }\n  el.classList.remove(\"off\"); el.classList.toggle(\"rev\", !!reverse);\n  el.style.setProperty(\"--dur\", clamp(2.6 - Math.log10(w)*0.55, .45, 2.6).toFixed(2)+\"s\");\n}\nlet lastLive = null, todaySeries = null;\nfunction renderLive(d){\n  lastLive = d;\n  const age = (Date.now() - (d.ts||Date.now()))/60000;\n  const pill = $(\"statusPill\");\n  if(mode === \"demo\"){ pill.className = \"pill demo\"; setText(\"statusText\",\"Date demonstrative\"); }\n  else if(!d.online || age > 20){ pill.className = \"pill bad\"; setText(\"statusText\",\"Invertor offline\"); }\n  else if(age > 8){ pill.className = \"pill warn\"; setText(\"statusText\",\"Date întârziate\"); }\n  else { pill.className = \"pill ok\"; setText(\"statusText\",\"Conectat\"); }\n  setText(\"modeText\", modeRo(d.mode));\n  setText(\"updatedText\", d.ts ? \"Actualizat la \"+hm(new Date(d.ts)) : \"—\");\n  if(d.device){ setText(\"devName\", (d.device.alias && d.device.alias !== d.device.sn ? d.device.alias : \"MPP Solar PIP-MAX 11 kW\")); setText(\"c-pn\", d.device.pn || \"—\"); setText(\"c-sn\", d.device.sn || \"—\"); }\n  setText(\"c-src\", mode === \"demo\" ? \"Simulare\" : \"Cloud DessMonitor\");\n  setText(\"c-last\", d.ts ? new Date(d.ts).toLocaleString(\"ro-RO\") : \"—\");\n\n  const pv = d.pv?.power, load = d.load?.power, bat = d.battery?.power, grid = d.grid?.power, soc = d.battery?.soc;\n  setText(\"v-pv\", fmtW(pv)); setText(\"v-load\", fmtW(load)); setText(\"v-grid\", d.grid?.present === false && !(grid > 15) ? \"absentă\" : fmtW(grid));\n  setText(\"v-bat\", isNum(soc) ? nf0.format(soc)+\" %\" : \"—\");\n  setText(\"v-batdir\", !isNum(bat) ? \"—\" : Math.abs(bat) < 15 ? \"în repaus\" : (bat > 0 ? \"+ \" : \"− \")+fmtW(Math.abs(bat)));\n  setText(\"v-loadpct\", isNum(d.load?.percent) ? nf0.format(d.load.percent)+\" % din invertor\" : \"\");\n  $(\"pvGlow\").setAttribute(\"opacity\", (0.05 + clamp((pv||0)/6000, 0, 1)*0.35).toFixed(2));\n  setFlow(\"f-pv\", pv, false); setFlow(\"f-load\", load, false); setFlow(\"f-grid\", grid, false);\n  setFlow(\"f-bat\", bat, isNum(bat) && bat < 0);\n  const fill = $(\"battFill\"); const fh = 23*clamp((soc||0)/100, 0, 1); fill.setAttribute(\"height\", fh.toFixed(1)); fill.setAttribute(\"y\", (11.5 - fh).toFixed(1));\n\n  // battery card\n  const arc = $(\"ringArc\"); arc.style.strokeDashoffset = (314.16*(1 - clamp((soc||0)/100,0,1))).toFixed(1);\n  const socCol = !isNum(soc) ? \"var(--muted)\" : soc <= settings.reserve ? \"var(--bad)\" : soc < 40 ? \"var(--warn)\" : \"var(--batt)\";\n  arc.style.stroke = socCol;\n  $(\"socText\").firstChild.nodeValue = isNum(soc) ? nf0.format(soc) : \"—\";\n  const charging = isNum(bat) && bat > 15, discharging = isNum(bat) && bat < -15;\n  setText(\"battState\", charging ? \"se încarcă\" : discharging ? \"se descarcă\" : \"în repaus\");\n  const chip = $(\"battChip\");\n  chip.className = \"tag chip \" + (!isNum(soc) ? \"\" : soc <= settings.reserve ? \"bad\" : soc < 40 ? \"warn\" : \"ok\");\n  chip.textContent = !isNum(soc) ? \"—\" : soc <= settings.reserve ? \"Nivel scăzut\" : soc < 40 ? \"Moderat\" : \"Bun\";\n  setText(\"b-v\", fmtU(d.battery?.voltage, \"V\", nf2)); setText(\"b-a\", isNum(d.battery?.current) ? nf1.format(d.battery.current)+\" A\" : \"—\"); setText(\"b-w\", fmtW(bat));\n  const capWh = settings.cap*1000;\n  if(charging && isNum(soc)){ setText(\"b-eta-k\",\"Plină în\"); setText(\"b-eta\", fmtDur((100-soc)/100*capWh / bat)); }\n  else if(discharging && isNum(soc)){ setText(\"b-eta-k\",\"Ajunge la rezervă în\"); setText(\"b-eta\", fmtDur(Math.max(0, soc - settings.reserve)/100*capWh / -bat)); }\n  else { setText(\"b-eta-k\",\"Estimare\"); setText(\"b-eta\",\"—\"); }\n  const autoH = isNum(soc) && load > 30 ? Math.max(0, soc - settings.reserve)/100*capWh / load : NaN;\n  $(\"k-auto\").innerHTML = \"\"; $(\"k-auto\").append(fmtDur(autoH));\n  setText(\"k-auto-sub\", isNum(load) ? \"la \"+fmtW(load)+\", până la \"+settings.reserve+\" %\" : \"la consumul actual\");\n\n  // pv strings\n  const rows = $(\"pvRows\"); rows.innerHTML = \"\";\n  const strs = d.pv?.strings || [];\n  const perMppt = 5500;\n  if(!strs.length){ rows.innerHTML = '<p class=\"muted small\" style=\"margin:0\">Invertorul nu raportează intrările separat.</p>'; }\n  strs.forEach((s, i) => {\n    const wrap = document.createElement(\"div\");\n    const r1 = document.createElement(\"div\"); r1.className = \"row\";\n    const k = document.createElement(\"span\"); k.className = \"k\"; k.textContent = \"Intrarea PV\"+(i+1);\n    const v = document.createElement(\"span\"); v.className = \"v\"; v.textContent = fmtW(s.w);\n    r1.append(k, v);\n    const bar = document.createElement(\"div\"); bar.className = \"bar\"; const sp = document.createElement(\"span\"); sp.style.width = clamp((s.w||0)/perMppt*100,0,100).toFixed(1)+\"%\"; bar.append(sp);\n    const sub = document.createElement(\"div\"); sub.className = \"muted small\"; sub.textContent = `${fmtU(s.v,\"V\")} · ${fmtU(s.a,\"A\")} · din ${fmtW(perMppt)} pe intrare`;\n    wrap.append(r1, bar, sub); rows.append(wrap);\n  });\n  // output\n  setText(\"o-v\", fmtU(d.output?.voltage, \"V\")); setText(\"o-hz\", fmtU(d.output?.freq, \"Hz\", nf2));\n  setText(\"o-pct\", isNum(d.load?.percent) ? nf0.format(d.load.percent)+\" %\" : \"—\");\n  $(\"o-bar\").style.width = clamp(d.load?.percent||0, 0, 100)+\"%\";\n  setText(\"o-temp\", fmtU(d.temp, \"°C\", nf0));\n  // grid\n  const gp = d.grid?.present ?? (d.grid?.voltage > 150);\n  const gc = $(\"gridChip\"); gc.className = \"tag chip \" + (gp ? \"ok\" : \"\"); gc.textContent = gp ? \"Prezentă\" : \"Absentă\";\n  setText(\"g-v\", fmtU(d.grid?.voltage, \"V\")); setText(\"g-hz\", fmtU(d.grid?.freq, \"Hz\", nf2)); setText(\"g-w\", fmtW(grid));\n  renderParams();\n}\n\nfunction renderKpis(s){\n  if(!s) return;\n  const prod = integrate(s.pv), cons = integrate(s.load), fromGrid = integrate(s.grid||[], 1);\n  $(\"k-prod\").innerHTML = \"\"; $(\"k-prod\").append(fmtKwh(prod)); const u1 = document.createElement(\"small\"); u1.textContent = \"kWh\"; $(\"k-prod\").append(u1);\n  $(\"k-cons\").innerHTML = \"\"; $(\"k-cons\").append(fmtKwh(cons)); const u2 = document.createElement(\"small\"); u2.textContent = \"kWh\"; $(\"k-cons\").append(u2);\n  const self = cons > 0 ? clamp((cons - fromGrid)/cons*100, 0, 100) : NaN;\n  $(\"k-self\").innerHTML = \"\"; $(\"k-self\").append(isNum(self) ? nf0.format(self) : \"—\"); const u3 = document.createElement(\"small\"); u3.textContent = \"%\"; $(\"k-self\").append(u3);\n  setText(\"g-today\", s.grid ? fmtKwh(fromGrid)+\" kWh\" : \"—\");\n  setText(\"k-prod-sub\", \"≈ \"+nf2.format(prod*settings.price)+\" lei economisiți\");\n}\n\n/* ---------- chart ---------- */\nfunction drawChart(host, s, day){\n  host.innerHTML = \"\";\n  const W = Math.max(280, host.clientWidth), H = Math.round(clamp(W*0.38, 190, 300));\n  const m = {l:42, r:10, t:10, b:24};\n  const ns = \"http://www.w3.org/2000/svg\";\n  const svg = document.createElementNS(ns, \"svg\"); svg.setAttribute(\"viewBox\", `0 0 ${W} ${H}`); svg.setAttribute(\"role\",\"img\"); svg.setAttribute(\"aria-label\",\"Grafic putere pe parcursul zilei\");\n  const el = (n, a, p = svg) => { const e = document.createElementNS(ns, n); for(const k in a) e.setAttribute(k, a[k]); p.append(e); return e; };\n  const d0 = new Date(day); d0.setHours(0,0,0,0); const t0 = d0.getTime(), t1 = t0 + 864e5;\n  const all = [...(s.pv||[]), ...(s.load||[]), ...(s.battery||[])].map(p => p[1]).filter(isNum);\n  if(!all.length){ host.innerHTML = '<p class=\"muted\" style=\"margin:30px 0;text-align:center\">Nu există date pentru ziua aceasta.</p>'; return; }\n  let ymax = Math.max(1000, ...all), ymin = Math.min(0, ...all);\n  const step = ymax - ymin > 6000 ? 2000 : 1000; ymax = Math.ceil(ymax/step)*step; ymin = Math.floor(ymin/step)*step;\n  const X = t => m.l + (t - t0)/(t1 - t0)*(W - m.l - m.r);\n  const Y = v => m.t + (ymax - v)/(ymax - ymin)*(H - m.t - m.b);\n  const defs = el(\"defs\", {});\n  const g = el(\"linearGradient\", {id:\"gpv\"+host.id, x1:0, y1:0, x2:0, y2:1}, defs);\n  el(\"stop\", {offset:0, \"stop-color\":\"#ffb547\", \"stop-opacity\":.55}, g); el(\"stop\", {offset:1, \"stop-color\":\"#ffb547\", \"stop-opacity\":0}, g);\n  for(let v = ymin; v <= ymax; v += step){\n    el(\"line\", {x1:m.l, x2:W-m.r, y1:Y(v), y2:Y(v), stroke: v === 0 ? \"rgba(160,180,255,.28)\" : \"rgba(160,180,255,.09)\"});\n    const tx = el(\"text\", {x:m.l-8, y:Y(v)+4, \"text-anchor\":\"end\", fill:\"#8c95b0\", \"font-size\":11}); tx.textContent = (v/1000)+\" kW\";\n  }\n  for(let h = 0; h <= 24; h += (W < 500 ? 6 : 3)){\n    const tx = el(\"text\", {x:X(t0+h*36e5), y:H-6, \"text-anchor\": h === 0 ? \"start\" : h === 24 ? \"end\" : \"middle\", fill:\"#8c95b0\", \"font-size\":11}); tx.textContent = pad2(h)+\":00\";\n  }\n  const path = (pts) => pts.filter(p => isNum(p[1])).map((p,i) => (i ? \"L\" : \"M\")+X(p[0]).toFixed(1)+\" \"+Y(p[1]).toFixed(1)).join(\"\");\n  if(s.pv?.length){\n    const pv = s.pv.filter(p => isNum(p[1]));\n    el(\"path\", {d: path(pv)+`L${X(pv[pv.length-1][0]).toFixed(1)} ${Y(0)}L${X(pv[0][0]).toFixed(1)} ${Y(0)}Z`, fill:`url(#gpv${host.id})`});\n    el(\"path\", {d: path(pv), fill:\"none\", stroke:\"#ffb547\", \"stroke-width\":2, \"stroke-linejoin\":\"round\"});\n  }\n  if(s.battery?.length) el(\"path\", {d: path(s.battery), fill:\"none\", stroke:\"#38e0c4\", \"stroke-width\":1.6, opacity:.9, \"stroke-linejoin\":\"round\"});\n  if(s.load?.length) el(\"path\", {d: path(s.load), fill:\"none\", stroke:\"#ff7d8f\", \"stroke-width\":2, \"stroke-linejoin\":\"round\"});\n  const last = s.pv?.[s.pv.length-1];\n  if(last && ymd(new Date(day)) === ymd(new Date())){ el(\"circle\", {cx:X(last[0]), cy:Y(last[1]), r:4.5, fill:\"#ffb547\", stroke:\"#0a0f1e\", \"stroke-width\":2}); }\n  const cursor = el(\"line\", {y1:m.t, y2:H-m.b, stroke:\"rgba(233,237,248,.35)\", \"stroke-dasharray\":\"3 3\", opacity:0});\n  host.append(svg);\n  const tip = document.createElement(\"div\"); tip.className = \"tip\"; host.append(tip);\n  const near = (arr, t) => { if(!arr?.length) return null; let lo = 0, hi = arr.length-1; while(hi - lo > 1){ const mid = (lo+hi)>>1; if(arr[mid][0] < t) lo = mid; else hi = mid; } const p = Math.abs(arr[lo][0]-t) < Math.abs(arr[hi][0]-t) ? arr[lo] : arr[hi]; return Math.abs(p[0]-t) < 36e5 ? p : null; };\n  const move = ev => {\n    const rect = svg.getBoundingClientRect(); const x = (ev.clientX - rect.left)/rect.width*W;\n    const t = t0 + (x - m.l)/(W - m.l - m.r)*(t1 - t0);\n    const p = near(s.pv, t) || near(s.load, t); if(!p){ tip.style.opacity = 0; cursor.setAttribute(\"opacity\",0); return; }\n    cursor.setAttribute(\"x1\", X(p[0])); cursor.setAttribute(\"x2\", X(p[0])); cursor.setAttribute(\"opacity\", 1);\n    tip.innerHTML = \"\";\n    const tt = document.createElement(\"div\"); tt.className = \"t\"; tt.textContent = hm(new Date(p[0])); tip.append(tt);\n    [[\"Producție\", near(s.pv,t), \"#ffb547\"], [\"Consum\", near(s.load,t), \"#ff7d8f\"], [\"Baterie\", near(s.battery,t), \"#38e0c4\"]].forEach(([n, q, c]) => {\n      if(!q) return; const r = document.createElement(\"div\"); const a = document.createElement(\"span\"); a.textContent = n; a.style.color = c; const b = document.createElement(\"b\"); b.textContent = fmtW(q[1]); r.append(a, b); tip.append(r);\n    });\n    tip.style.opacity = 1;\n    const px = (X(p[0])/W)*rect.width; const tw = tip.offsetWidth;\n    tip.style.left = clamp(px + 12 > rect.width - tw ? px - tw - 12 : px + 12, 0, rect.width - tw)+\"px\"; tip.style.top = \"8px\";\n  };\n  svg.addEventListener(\"pointermove\", move); svg.addEventListener(\"pointerdown\", move);\n  svg.addEventListener(\"pointerleave\", () => { tip.style.opacity = 0; cursor.setAttribute(\"opacity\",0); });\n}\n\n/* ---------- params ---------- */\nfunction renderParams(){\n  const host = $(\"paramGroups\"); const q = $(\"paramSearch\").value.trim().toLowerCase();\n  const list = (lastLive?.params || []).filter(p => !q || (p.par+\" \"+p.group).toLowerCase().includes(q));\n  host.innerHTML = \"\";\n  const groups = {}; list.forEach(p => (groups[p.group || \"Altele\"] ||= []).push(p));\n  if(!list.length){ host.innerHTML = '<p class=\"muted\">Niciun parametru găsit.</p>'; return; }\n  Object.entries(groups).forEach(([g, items]) => {\n    const card = document.createElement(\"div\"); card.className = \"card\";\n    const h = document.createElement(\"h2\"); h.textContent = g; card.append(h);\n    const t = document.createElement(\"table\"); t.className = \"params\";\n    items.forEach(p => { const tr = document.createElement(\"tr\"); const a = document.createElement(\"td\"); a.textContent = p.par; const b = document.createElement(\"td\"); b.textContent = (p.val ?? \"—\") + (p.unit ? \" \"+p.unit : \"\"); tr.append(a, b); t.append(tr); });\n    card.append(t); host.append(card);\n  });\n}\n\n/* ---------- history view ---------- */\nlet histDate = new Date();\nasync function loadHistory(){\n  $(\"dayPick\").value = ymd(histDate); $(\"dayPick\").max = ymd(new Date());\n  $(\"dayNext\").disabled = ymd(histDate) >= ymd(new Date());\n  try{\n    const s = await getDay(histDate);\n    drawChart($(\"chartDay\"), s, histDate); histSeries = s;\n    const prod = integrate(s.pv), cons = integrate(s.load);\n    setText(\"d-prod\", fmtKwh(prod)+\" kWh\"); setText(\"d-cons\", fmtKwh(cons)+\" kWh\");\n    const pk = (s.pv||[]).reduce((a, p) => p[1] > (a?.[1] ?? -1) ? p : a, null);\n    setText(\"d-peak\", pk ? fmtW(pk[1]) : \"—\"); setText(\"d-peak-t\", pk ? \"la \"+hm(new Date(pk[0])) : \"\");\n    setText(\"d-save\", nf2.format(prod*settings.price)+\" lei\"); setText(\"d-save-sub\", \"la \"+nf2.format(settings.price)+\" lei/kWh\");\n  }catch(e){ if(e.message !== \"PIN\") $(\"chartDay\").innerHTML = '<p class=\"muted\" style=\"text-align:center;margin:30px 0\">Nu am putut încărca ziua: '+String(e.message).replace(/[<>&]/g,\"\")+'</p>'; }\n}\nlet histSeries = null;\n\n/* ---------- loops ---------- */\nasync function refreshLive(){\n  try{ const d = await getLive(); renderLive(d); if(mode === \"live\") banner(null); }\n  catch(e){ if(e.message !== \"PIN\"){ $(\"statusPill\").className = \"pill bad\"; setText(\"statusText\",\"Fără date\"); banner(\"err\", \"<b>Nu primesc date.</b> \"+String(e.message).replace(/[<>&]/g,\"\")); } }\n}\nasync function refreshToday(){\n  try{ const s = await getDay(new Date()); todaySeries = s; renderKpis(s); drawChart($(\"chartToday\"), s, new Date()); setText(\"todayNote\", mode === \"demo\" ? \"simulare\" : \"din 5 în 5 minute\"); }\n  catch(e){ if(e.message !== \"PIN\") $(\"chartToday\").innerHTML = '<p class=\"muted\" style=\"text-align:center;margin:30px 0\">Graficul zilei nu e disponibil încă.</p>'; }\n}\n\n/* ---------- tabs ---------- */\nfunction showView(v){\n  document.querySelectorAll(\"nav.tabs button\").forEach(b => b.setAttribute(\"aria-selected\", String(b.dataset.view === v)));\n  document.querySelectorAll(\".view\").forEach(s => s.classList.toggle(\"active\", s.id === \"view-\"+v));\n  if(v === \"istoric\") loadHistory();\n  if(v === \"acasa\" && todaySeries) drawChart($(\"chartToday\"), todaySeries, new Date());\n  try{ if(location.hash !== \"#\"+v) history.replaceState(null, \"\", \"#\"+v); }catch(e){}\n}\ndocument.querySelectorAll(\"nav.tabs button\").forEach(b => b.addEventListener(\"click\", () => showView(b.dataset.view)));\n\n/* ---------- lock ---------- */\nfunction showLock(on){ $(\"lock\").classList.toggle(\"show\", on); if(on) setTimeout(() => $(\"pinInput\").focus(), 50); }\n$(\"pinForm\").addEventListener(\"submit\", async e => {\n  e.preventDefault(); pin = $(\"pinInput\").value.trim(); $(\"pinErr\").textContent = \"\";\n  try{ const r = await fetch(\"/api/auth\", {headers:{\"x-pin\":pin}, cache:\"no-store\"}); if(r.status === 401) throw 0; store.set(\"pin\", pin); showLock(false); start(); }\n  catch(_){ $(\"pinErr\").textContent = \"PIN greșit. Încearcă din nou.\"; }\n});\n$(\"logoutBtn\").addEventListener(\"click\", () => { store.set(\"pin\",\"\"); pin = \"\"; if(mode === \"live\") showLock(true); });\n\n/* ---------- settings ---------- */\n$(\"setCap\").value = settings.cap; $(\"setPrice\").value = settings.price; $(\"setReserve\").value = settings.reserve; $(\"setDemo\").checked = settings.demo;\nconst onSet = () => {\n  settings.cap = clamp(parseFloat($(\"setCap\").value)||10, 1, 200); settings.price = clamp(parseFloat($(\"setPrice\").value)||0, 0, 10); settings.reserve = clamp(parseFloat($(\"setReserve\").value)||0, 0, 80);\n  store.set(\"cap\", settings.cap); store.set(\"price\", settings.price); store.set(\"reserve\", settings.reserve);\n  if(lastLive) renderLive(lastLive); if(todaySeries) renderKpis(todaySeries);\n};\n[\"setCap\",\"setPrice\",\"setReserve\"].forEach(id => $(id).addEventListener(\"change\", onSet));\n$(\"setDemo\").addEventListener(\"change\", async () => { settings.demo = $(\"setDemo\").checked; store.set(\"demo\", settings.demo); await detect(); start(); });\n$(\"paramSearch\").addEventListener(\"input\", renderParams);\n$(\"dayPick\").addEventListener(\"change\", () => { const v = $(\"dayPick\").value; if(v){ const [y,mo,da] = v.split(\"-\").map(Number); histDate = new Date(y, mo-1, da); loadHistory(); } });\n$(\"dayPrev\").addEventListener(\"click\", () => { histDate = new Date(histDate.getTime() - 864e5); loadHistory(); });\n$(\"dayNext\").addEventListener(\"click\", () => { histDate = new Date(histDate.getTime() + 864e5); loadHistory(); });\nlet rT; window.addEventListener(\"resize\", () => { clearTimeout(rT); rT = setTimeout(() => { if(todaySeries) drawChart($(\"chartToday\"), todaySeries, new Date()); if(histSeries && $(\"view-istoric\").classList.contains(\"active\")) drawChart($(\"chartDay\"), histSeries, histDate); }, 150); });\n\n/* ---------- start ---------- */\nlet timers = [];\nfunction start(){\n  timers.forEach(clearInterval); timers = [];\n  if(mode === \"demo\") banner(\"demo\", \"<b>Mod demonstrativ.</b> Valorile sunt simulate. După ce pornești serverul NicuInvertor în Cloudflare, aplicația arată automat datele reale ale invertorului.\");\n  else banner(null);\n  refreshLive(); refreshToday();\n  timers.push(setInterval(refreshLive, 30000), setInterval(refreshToday, 300000));\n}\n(async () => {\n  await detect();\n  const h = (location.hash || \"\").slice(1); if([\"istoric\",\"detalii\",\"setari\"].includes(h)) showView(h);\n  if(mode === \"live\" && !pin) return; // wait for PIN\n  start();\n})();\ndocument.addEventListener(\"visibilitychange\", () => { if(!document.hidden && (mode === \"demo\" || pin)) refreshLive(); });\n})();\n<\/script>\n</body>\n</html>\n";

